package com.hmdp.ai.infrastructure.redis;
import com.hmdp.ai.domain.tool.ToolRateLimitPort;import org.redisson.api.RRateLimiter;import org.redisson.api.RateIntervalUnit;import org.redisson.api.RateType;import org.redisson.api.RedissonClient;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.stereotype.Component;
@Component public class RedisToolRateLimitAdapter implements ToolRateLimitPort {private final RedissonClient redis;public RedisToolRateLimitAdapter(@Qualifier("businessRedissonClient") RedissonClient redis){this.redis=redis;}@Override public boolean acquire(String tenant,String tool,int permits){RRateLimiter l=redis.getRateLimiter("hmdp:ai:tool:rate:"+tenant+":"+tool);l.trySetRate(RateType.OVERALL,Math.max(1,permits),1,RateIntervalUnit.SECONDS);return l.tryAcquire();}}
